-- Driving Theory 4 All — Авто
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'drivingtheory4all.co.uk' OR LOWER(`name`) = 'driving theory 4 all')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Driving Theory 4 All', NULL, 'https://www.drivingtheory4all.co.uk', NULL, NULL, 'Підготовка до британського теоретичного іспиту DVSA з AI-тренером: авто, мотоцикл, вантажівка, автобус, інструктор.', 'Preparation for the UK DVSA theory test with an AI trainer: car, motorcycle, lorry, bus and instructor.', 'Сайт і застосунки для iOS та Android, що готують до теоретичного іспиту й тесту на сприйняття небезпек (hazard perception) у Великій Британії. Є окремі курси для категорій Car, Motorcycle, LGV, PCV, ADI Part 1, а також модулі CPC Module 2 для водіїв вантажівок і автобусів. AI Personal Trainer аналізує ваш прогрес, підказує, на які теми звернути увагу, і складає персональний план повторення. У складі — ліцензовані DVSA питання з поясненнями, необмежені пробні тести на час, Highway Code, понад 900 питань про дорожні знаки та відеокліпи для тренування реакції на небезпеки. Прогрес синхронізується між пристроями.', 'A website and iOS and Android apps that prepare you for the UK theory test and hazard perception test. There are separate courses for Car, Motorcycle, LGV, PCV and ADI Part 1, plus CPC Module 2 modules for lorry and bus drivers. The AI Personal Trainer analyses your progress, points out topics to focus on and builds a personal revision plan. It includes DVSA-licensed questions with explanations, unlimited timed mock tests, the Highway Code, over 900 road sign questions and video clips for hazard perception practice. Progress syncs across devices.', 'AI Personal Trainer з персональним планом повторення
Ліцензовані DVSA питання з поясненнями
Необмежені пробні тести на час
Кліпи для тесту hazard perception
Курси для авто, мото, LGV, PCV, ADI і CPC', 'AI Personal Trainer with a personal revision plan
DVSA-licensed questions with explanations
Unlimited timed mock tests
Hazard perception clips
Courses for car, motorcycle, LGV, PCV, ADI and CPC', 'Кандидати у водії, мотоциклісти, водії вантажівок і автобусів та майбутні інструктори у Великій Британії.', 'Learner drivers, motorcyclists, lorry and bus drivers and trainee instructors in the UK.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-09 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'drivingtheory4all.co.uk' OR LOWER(`name`) = 'driving theory 4 all') ORDER BY `id` LIMIT 1);
