-- Driving-Tests.org — Авто
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'driving-tests.org' OR LOWER(`name`) = 'driving-tests.org')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Driving-Tests.org', NULL, 'https://driving-tests.org', NULL, NULL, 'Практичні тести DMV для всіх штатів США з адаптивною практикою та AI-репетитором DMV Genie.', 'DMV practice tests for every US state with adaptive practice and the DMV Genie AI tutor.', 'Сервіс підготовки до письмового іспиту DMV на дозвіл (permit) і водійське посвідчення в США. Тести складено за довідником конкретного штату, а Challenge Bank автоматично повертає питання, на які ви відповіли неправильно, доки ви їх не засвоїте. За даними сайту, практика адаптується до вас за допомогою AI, є зображення, симуляційні відео й кліпи на сприйняття небезпек. У Premium входить AI-репетитор DMV Genie: на будь-яке питання можна запитати «чому?» й отримати пояснення англійською, іспанською чи російською, побудоване на довіднику вашого штату. Також у Premium — шпаргалки PDF, понад 500 флеш-карток, необмежені симулятори іспиту й індикатор готовності.', 'A service that prepares you for the US DMV written test for a permit and driver''s license. Tests follow your state''s handbook, and the Challenge Bank automatically retests you on missed questions until you get them right. According to the site, practice adapts to you with AI, and there are images, simulated videos and hazard perception clips. Premium includes the DMV Genie AI tutor: you can ask "why?" on any question and get an explanation in English, Spanish or Russian, based on your state handbook. Premium also adds PDF cheat sheets, 500+ flashcards, unlimited exam simulators and a readiness meter.', 'Тести за довідником вашого штату
AI-репетитор DMV Genie (EN, ES, RU)
Challenge Bank — повторення помилок
Симулятор іспиту й індикатор готовності
Шпаргалки PDF і флеш-картки', 'Tests based on your state handbook
DMV Genie AI tutor (EN, ES, RU)
Challenge Bank for missed questions
Exam simulator and readiness meter
PDF cheat sheets and flashcards', 'Підлітки й дорослі в США, які складають письмовий іспит DMV на дозвіл або посвідчення водія.', 'Teens and adults in the US taking the DMV written test for a permit or driver''s license.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-09 00:00:00' FROM DUAL WHERE @new = 1;
