-- iFahrer — Авто
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'ifahrer.de' OR LOWER(`name`) = 'ifahrer')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'iFahrer', NULL, 'https://ifahrer.de', NULL, NULL, 'Застосунок для підготовки до теоретичного іспиту на німецьке посвідчення з AI-поясненнями та розпізнаванням знаків.', 'An app for the German driving theory test with AI explanations and road sign recognition.', 'iFahrer допомагає готуватися до теоретичного іспиту в Німеччині за офіційною базою питань. AI-асистент пояснює, чому правильна саме ця відповідь, а за фото дорожнього знака бот його розпізнає та пояснює значення. Є режим практики без обмеження часу та режим іспиту з таймером, історія іспитів, відеопояснення, озвучування питань і відстеження прогресу. На сайті можна шукати питання за категоріями посвідчення: A, A1, A2, AM, B, C, C1, CE, D, D1, L, T і Mofa, а також переглядати каталог знаків. Інтерфейс сайту доступний кількома мовами.', 'iFahrer helps you prepare for the German theory test using the official question database. The AI assistant explains why a given answer is correct, and the bot recognises a road sign from a photo and explains its meaning. There is a practice mode without a time limit and a timed exam mode, exam history, video explanations, read-aloud questions and progress tracking. On the website you can browse questions by license class: A, A1, A2, AM, B, C, C1, CE, D, D1, L, T and Mofa, and look up road signs. The website interface is available in several languages.', 'AI-пояснення до питань
Розпізнавання знаків за фото
Режим практики й режим іспиту
Категорії A, B, C, D, L, T, Mofa та інші
Озвучування питань і відеопояснення', 'AI explanations for questions
Road sign recognition from photos
Practice mode and exam mode
Classes A, B, C, D, L, T, Mofa and more
Read-aloud questions and video explanations', 'Кандидати у водії в Німеччині, зокрема ті, кому зручніше вчитися з поясненнями іншою мовою.', 'Learner drivers in Germany, including those who prefer explanations in another language.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-09 00:00:00' FROM DUAL WHERE @new = 1;
