INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Körkortonline.se', NULL, 'https://korkortonline.se', NULL, NULL, 'Шведський сайт із теорією та питаннями до іспиту на посвідчення водія, аналітикою помилок на основі AI.', 'A Swedish site with theory and practice questions for the driving license test, with AI-based error insights.', 'Körkortonline.se працює з 2007 року й допомагає готуватися до теоретичного іспиту (teoriprov) на шведське посвідчення водія. Безкоштовно можна читати теорію та правила дорожнього руху, пробувати демо питань і брати участь у форумі. Платний доступ відкриває 1000 питань і необмежену кількість пробних тестів. За словами сайту, з допомогою AI вони проаналізували анонімні дані відповідей і з''ясували, де учні найчастіше помиляються та які типи питань найважчі. Ці висновки (provinsikter) входять у повний доступ.', 'Körkortonline.se has been online since 2007 and helps you prepare for the Swedish driving theory test (teoriprov). For free you can read theory and traffic rules, try a question demo and join the forum. Paid access unlocks 1,000 questions and unlimited practice tests. According to the site, they used AI to analyse anonymous answer data and find where learners most often make mistakes and which question types are the hardest. These insights (provinsikter) are part of full access.', '1000 питань до теоретичного іспиту
Необмежені пробні тести
Висновки про типові помилки з аналізу AI
Безкоштовна теорія й правила
Форум', '1,000 theory test questions
Unlimited practice tests
AI-derived insights into common mistakes
Free theory and traffic rules
Forum', 'Ті, хто складає теоретичний іспит на посвідчення водія у Швеції.', 'People taking the driving theory test in Sweden.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-09 00:00:00' FROM DUAL WHERE @new = 1;
