SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'green-way.com.ua' OR LOWER(`name`) = 'green way')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Green Way', NULL, 'https://green-way.com.ua', NULL, NULL, 'Український сервіс для вивчення ПДР і тестів до іспиту в сервісному центрі МВС за всіма категоріями.', 'A Ukrainian service for learning traffic rules and practicing for the MVS service center exam in all categories.', 'GREEN-WAY працює з 2016 року й допомагає готуватися до теоретичного іспиту в сервісних центрах МВС. У ньому 64 теми ПДР і близько 2500 питань, а також модулі з безпеки руху, першої допомоги й права. Режими: питання до теми, 20 випадкових питань, іспит із розподілом питань як у СЦ, 100 найчастіших помилок, робота над помилками й обране. Є повний текст ПДР з ілюстраціями, знаки й розмітка, таблиця штрафів, конструктор дорожніх ситуацій, ігри з ПДР і коментарі викладачів до питань. Категорію (A1, A, B1, B, C1, C, D1, D, BE, CE, DE, T) обирають у налаштуваннях. Є застосунки для Android та iOS.', 'GREEN-WAY has been running since 2016 and helps you prepare for the theory exam at MVS service centers in Ukraine. It has 64 traffic rule topics and about 2,500 questions, plus modules on road safety, first aid and law. Modes: questions by topic, 20 random questions, an exam with the same question distribution as at the service center, the 100 most common mistakes, mistake review and favourites. There is the full text of the traffic rules with illustrations, signs and markings, a fines table, a road situation builder, traffic rule games and teachers'' comments on questions. The category (A1, A, B1, B, C1, C, D1, D, BE, CE, DE, T) is chosen in settings. Android and iOS apps are available.', 'Близько 2500 питань і 64 теми ПДР
Режим іспиту як у сервісному центрі МВС
Категорії A, B, C, D, E, T
Конструктор дорожніх ситуацій та ігри
Коментарі викладачів до питань', 'About 2,500 questions and 64 traffic rule topics
Exam mode as at the MVS service center
Categories A, B, C, D, E, T
Road situation builder and games
Teachers'' comments on questions', 'Кандидати у водії в Україні, курсанти автошкіл і викладачі.', 'Learner drivers in Ukraine, driving school students and teachers.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-09 00:00:00' FROM DUAL WHERE @new = 1;
