INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Aceable Drivers Ed', NULL, 'https://www.aceable.com/drivers-ed/', NULL, NULL, 'Схвалені штатами онлайн-курси водіння й підготовка до permit-тесту в США з відео та інтерактивними уроками.', 'State-approved online drivers ed courses and permit test prep in the US with videos and interactive lessons.', 'Aceable пропонує сертифіковані штатами онлайн-курси для підлітків і дорослих: короткі уроки, відео, спливні питання й озвучення. Курси є для Каліфорнії, Флориди, Джорджії, Іллінойсу, Невади, Огайо, Оклахоми й Техасу, зокрема батьківський курс у Техасі та обов''язковий курс DETS у Флориді. До курсів входять навчальні посібники, практичні тести до письмового іспиту DMV й інструменти для батьків. Окремо є підготовка до permit-тесту, захисне водіння та курси для електровелосипедів і скутерів. Навчатися можна з будь-якого пристрою.', 'Aceable offers state-certified online courses for teens and adults: short lessons, videos, pop-up questions and voiceover. Courses are available for California, Florida, Georgia, Illinois, Nevada, Ohio, Oklahoma and Texas, including parent-taught drivers ed in Texas and the required DETS course in Florida. Courses include study guides, practice tests for the DMV written exam and parent tools. There is also separate permit test prep, defensive driving and courses for e-bikes and scooters. You can learn on any device.', 'Схвалені штатами курси водіння
Практичні тести до іспиту DMV
Відео й інтерактивні уроки
Інструменти для батьків
Захисне водіння, е-велосипеди й скутери', 'State-approved drivers ed courses
DMV written test practice
Videos and interactive lessons
Parent tools
Defensive driving, e-bikes and scooters', 'Підлітки, дорослі новачки та батьки в штатах США, де курси Aceable схвалені.', 'Teens, adult beginners and parents in US states where Aceable courses are approved.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-09 00:00:00' FROM DUAL WHERE @new = 1;
