INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'DriversEd.com', NULL, 'https://www.driversed.com', NULL, NULL, 'Онлайн-курси водіння, traffic school і підготовка до permit-тесту для штатів США з необмеженими практичними тестами.', 'Online drivers ed, traffic school and permit test prep for US states with unlimited practice tests.', 'DriversEd.com понад 20 років проводить онлайн-навчання водінню в США й навчило понад 3 мільйони водіїв. Оберіть штат і програму: курси для підлітків і дорослих, traffic school, підготовка до іспиту (Test Prep) та уроки водіння з інструктором. Курси, схвалені штатами, містять необмежені практичні тести до permit-іспиту, доступні в будь-який час на будь-якому пристрої й у застосунку DriversEd.com. Є довідка про DMV та блог. Підтримка працює 7 днів на тиждень.', 'DriversEd.com has provided online driver training in the US for over 20 years and trained more than 3 million drivers. Pick your state and program: courses for teens and adults, traffic school, test prep and in-car lessons with an instructor. State-approved courses include unlimited permit practice tests, available anytime on any device and in the DriversEd.com app. There is DMV information and a blog. Support works 7 days a week.', 'Курси для підлітків і дорослих за штатами
Необмежені практичні permit-тести
Traffic school і Test Prep
Уроки водіння з інструктором
Застосунок DriversEd.com', 'Teen and adult courses by state
Unlimited permit practice tests
Traffic school and test prep
In-car lessons with an instructor
DriversEd.com app', 'Підлітки й дорослі в США, які отримують дозвіл чи посвідчення або мають пройти traffic school.', 'Teens and adults in the US getting a permit or license or required to take traffic school.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-09 00:00:00' FROM DUAL WHERE @new = 1;
